import React, { useState, useEffect } from 'react';
import './AdminMessages.css';
import Sidebar from './Sidebar'; 
import PageTitle from '../PageTitle';

function AdminMessages() {
  const [messages, setMessages] = useState([]); // Mesajları tutacak state
  const [loading, setLoading] = useState(true); // Yükleniyor durumu
  const [error, setError] = useState(null); // Hata durumu

  useEffect(() => {
    // Mesajları al
    const fetchMessages = async () => {
      try {
        const response = await fetch('/api/notifications');
        const data = await response.json();
        setMessages(data); // Gelen mesajları state'e ata
      } catch (err) {
        setError("Mesajlar yüklenirken bir hata oluştu."); // Hata durumu
      } finally {
        setLoading(false); // Yükleme tamamlandı
      }
    };

    fetchMessages(); // Mesajları çek
  }, []); // Component mount olduğunda çalışacak

  return (
    <>
      <PageTitle title='Gelen Mesajlar'/>
      <div className="admin-panel">
        <Sidebar /> 
        <main className="main-content">
          <h1>Gelen Mesajlar</h1>
          <div className="messages-container">
            {loading ? (
              <p>Yükleniyor...</p>
            ) : error ? (
              <p>{error}</p>
            ) : messages.length === 0 ? (
              <p>Henüz mesaj yok.</p>
            ) : (
              <ul>
                {messages.map((message) => (
                  <li key={message._id}>
                    <p><strong>İsim:</strong> {message.isim}</p>
                    <p><strong>Konusu:</strong> {message.konu}</p>
                    <p><strong>Mesaj:</strong> {message.mesaj}</p>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </main>
      </div>
    </>
  );
}

export default AdminMessages;
